package run.ikaros.password; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/vaults/{vaultId}/export") public class PasswordExportController{private final PasswordExportService service;public PasswordExportController(PasswordExportService s){service=s;}@GetMapping public Mono<EncryptedVaultExport> export(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.export(a,vaultId);}}
